"""Build planned boundary scenarios from individually assessed confirmed requirements.
No application execution or independent-review approval occurs here.
"""
import json, hashlib, subprocess
from pathlib import Path
P=Path(__file__).resolve().parents[1]
R=json.loads((P/'requirements.json').read_text())
DATA={}
def rows(package, text):
    for line in text.strip().splitlines():
        n,title,setup,action,result=line.split('|')
        rid=f'{package}-{n}'
        assert rid not in DATA
        DATA[rid]={'title':title,'setup':setup,'action':action,'result':result}
