COMMON_PRE=[
 'PLAN ONLY. Execute later on an available authorized app/test environment. If a required route, resource, policy, observable record or oracle is unavailable, mark the affected vector unproven/blocked; do not fabricate a result or infer approval. No app location is required during design.',
 'Create a fresh named synthetic fixture per vector through supported customer/admin/service boundaries; reopen it to verify the stated starting state. Keep unrelated control records and record before balances/statuses. Do not inspect internal code/storage or assume a particular database, API shape or worker design.',
 'Resolve market, currencies/minor units, rule versions, cutoffs/inclusivity, qualifications, role permissions and operational/visual standards from supplied confirmed configuration at execution time. Compute expected totals/sets independently before action; unknown business values remain pending, never adopt fixture values as business policy. Numeric examples are synthetic probes.',
 'Credentials stay in an external secure store and are referenced only; capture redacted screenshots/receiver histories. Real-mode assertions use an authorized real-contract test environment and separately verified integration resources when later available; isolated app test mode is a distinct branch and does not prove real integration. Never initiate unapproved production charges, shipping or restore operations.'
]
COMMON_ACTION_END='After each vector, reload/re-enter through the appropriate authorized user or external receiver boundary and compare the observed state with the independently recorded before state and expected result. Check named unrelated control records. Record failures and missing oracles per vector; resetting one vector must not mask an earlier failure.'

def method(mid,title,setup,action,result,refs):
 result_method={'id':mid,'kind':'ai_check','description':'Planned reusable AI-operated boundary procedure: '+title+'. Re-run with fresh fixtures for every enumerated vector; not executed evidence.',
 'preconditions':COMMON_PRE+[setup],
 'actions':['Read the confirmed requirement(s) '+', '.join(refs)+' from requirements.json. Enumerate every setup vector, including all stated table rows and independent omissions; record concrete fixture IDs, role, mode and expected oracle before execution.',action,'Assert: '+result,COMMON_ACTION_END],
 'evidence_expected':['For EACH vector: redacted setup/configuration and before-state record; ordered customer/staff action trace showing the actual action; final and reloaded user-visible page or supported external-system result. No execution evidence exists at design time.','Assertion evidence must demonstrate: '+result,'Where money, quantities, notifications or repeated actions are involved: before/after scoped balances, transaction/message/record identifiers and receiver history sufficient to detect a duplicate, wrong recipient or wrong mode. A screenshot of a button click alone is insufficient.']}
 for field in ('preconditions','actions','evidence_expected'):
  result_method[field]='\n\n'.join(f'{n}. {text}' for n,text in enumerate(result_method[field],1))
 return result_method

def build():
 req={x['id']:x for x in R['items']}
 assert set(DATA)==set(req), {'missing':sorted(set(req)-set(DATA)),'extra':sorted(set(DATA)-set(req))}
 project=json.loads((P/'project.json').read_text())
 assert project['requirements_sha256']==hashlib.sha256((P/'requirements.json').read_bytes()).hexdigest(), 'snapshot changed; import required'
 for file in ['scenarios.json','methods.json']:
  subprocess.run(['git','check-ignore','--quiet',str(P/file)],check=True)
 s=json.loads((P/'scenarios.json').read_text()); m=json.loads((P/'methods.json').read_text())
 # Never discard preexisting items or edit a method used by a white-box scenario.
 sids={x['id'] for x in s['items']}; mids={x['id'] for x in m['items']}
 new_s=[]; new_m=[]
 for rid,item in DATA.items():
  sid='BB-'+rid; mid='AI-'+rid
  assert sid not in sids and mid not in mids, 'Existing design requires deliberate merge rather than overwrite'
  new_s.append({'id':sid,'kind':'black_box','title':item['title'],'requirement_ids':[rid],'expected':item['result'],'method_ids':[mid]})
  mm=method(mid,item['title'],item['setup'],item['action'],item['result'],[rid])
  if rid in TRANSITIONS:
   mm['transition_matrix']={'allowed_adjacency':TRANSITIONS[rid], 'execution_rule':'For each dimension/type create a fresh case for every listed source→target pair with all prerequisites from the confirmed requirement table. Repeat with each required prerequisite independently absent. From every named state (including terminal states), attempt every other unlisted target through offered controls or supported documented boundary and assert no prohibited business-state change. A listed edge is conditional, never blanket permission; record outcome per edge/prerequisite. Repeated same-state observations are not new business effects.','guard_oracle':req[rid]['text']}
  new_m.append(mm)
 for j in JOURNEYS:
  assert set(j['refs'])<=set(req)
  mid='AI-journey-'+j['id']; assert mid not in mids
  result=' '.join(x[1] for x in j['phases'])
  new_m.append(method(mid,j['title'],j['setup'],j['action'],result,j['refs']))
  for phase,outcome in j['phases']:
   sid='BB-journey-'+j['id']+'-'+phase; assert sid not in sids
   # All linked requirements are exercised by the complete shared method; each
   # phase expectation additionally retains its full-journey observable contract.
   new_s.append({'id':sid,'kind':'black_box','title':j['title']+' — '+phase,'requirement_ids':j['refs'],'expected':outcome+' Full journey must also satisfy: '+result,'method_ids':[mid]})
 s['items'].extend(new_s); m['items'].extend(new_m)
 # Completeness set only after all 188 individually authored matrices and the
 # interaction journeys have been assessed and every reference validated.
 assert set(req)<={r for x in s['items'] if x['kind']=='black_box' for r in x['requirement_ids']}
 assert len({x['id'] for x in s['items']})==len(s['items'])
 assert len({x['id'] for x in m['items']})==len(m['items'])
 known={x['id'] for x in m['items']}
 assert all(set(x['method_ids'])<=known for x in s['items'])
 s['black_box_complete']=True
 # white_box_complete is intentionally preserved, never asserted here.
 for name,data in [('methods.json',m),('scenarios.json',s)]:
  (P/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
 assessment={'stage':'analyst_scenario_design','execution':'not_run','independent_review':'not_authored; pending',
 'requirements_sha256':project['requirements_sha256'],'requirements_assessed':len(req),'new_scenarios':len(new_s),'new_ai_methods':len(new_m),
 'scope':'Confirmed external behaviors only. Every setup vector and table row is mandatory, not a menu from which the executor chooses the easiest case. Formal business values remain pending-business-inputs.json dependencies.',
 'assessment_rule':'For every ID, identify concrete pre-state/mode/actor, act at supported user/external boundary and compare visible outcome. Exception, boundary, transition and interaction vectors appear where the confirmed behavior makes them relevant. Independent reviewer must still challenge omitted vectors.',
 'items':[{'requirement_id':rid,'scenario_id':'BB-'+rid,'operation_modes_and_user_states':x['setup'],'action_and_variants':x['action'],'incorrect_behavior_detection':x['result']} for rid,x in DATA.items()]}
 (P/'scenario-design-assessment.json').write_text(json.dumps(assessment,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({k:assessment[k] for k in ['requirements_assessed','new_scenarios','new_ai_methods','execution','independent_review']}))
if __name__=='__main__': build()
